@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HistoryReportScreen(
    historyList: List<DetectionHistoryEntity>,
    feedbackMessage: String?,
    onUpdateCatatan: (id: Int, catatanBaru: String) -> Unit,
    onDeleteItem: (id: Int) -> Unit,
    onDeleteAll: () -> Unit,
    onConsultChatbot: (DetectionHistoryEntity) -> Unit,
    onClearFeedback: () -> Unit,
    onBack: (() -> Unit)? = null,
    modifier: Modifier = Modifier
) {
    val snackbarHostState = remember { SnackbarHostState() }
    var showClearAllDialog by remember { mutableStateOf(false) }
    var editingItem by remember { mutableStateOf<DetectionHistoryEntity?>(null) }
    var editedCatatan by remember { mutableStateOf("") }

    LaunchedEffect(feedbackMessage) {
        if (feedbackMessage != null) {
            snackbarHostState.showSnackbar(feedbackMessage)
            onClearFeedback()
        }
    }

    Scaffold(
        modifier = modifier,
        containerColor = HistBackgroundLight,
        snackbarHost = { SnackbarHost(snackbarHostState) },
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "Riwayat Pemeriksaan",
                        color = HistTextPrimary,
                        fontWeight = FontWeight.SemiBold
                    )
                },
                navigationIcon = {
                    if (onBack != null) {
                        IconButton(onClick = onBack) {
                            Icon(
                                imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                                contentDescription = "Kembali",
                                tint = HistTextPrimary
                            )
                        }
                    }
                },
                actions = {
                    if (historyList.isNotEmpty()) {
                        IconButton(onClick = { showClearAllDialog = true }) {
                            Icon(
                                imageVector = Icons.Filled.DeleteSweep,
                                contentDescription = "Hapus semua riwayat",
                                tint = RedError
                            )
                        }
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        }
    ) { padding ->
        if (historyList.isEmpty()) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding)
                    .padding(24.dp),
                contentAlignment = Alignment.Center
            ) {
                EmptyHistoryCard()
            }
        } else {
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding),
                contentPadding = PaddingValues(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                items(historyList, key = { it.id }) { item ->
                    HistoryReportCard(
                        item = item,
                        onEditClick = {
                            editingItem = item
                            editedCatatan = item.catatanKeluhan
                        },
                        onDeleteClick = { onDeleteItem(item.id) },
                        onConsultClick = { onConsultChatbot(item) }
                    )
                }
            }
        }
    }

    if (showClearAllDialog) {
        AlertDialog(
            onDismissRequest = { showClearAllDialog = false },
            title = { Text("Hapus Semua Riwayat?", fontWeight = FontWeight.SemiBold) },
            text = { Text("Seluruh riwayat pemeriksaan yang tersimpan di perangkat ini akan dihapus permanen.") },
            confirmButton = {
                Button(
