                    colors = ButtonDefaults.buttonColors(containerColor = RedError)
                ) {
                    Text("Hapus Semua")
                }
            },
            dismissButton = {
                TextButton(onClick = { showClearAllDialog = false }) {
                    Text("Batal", color = HistTextMuted)
                }
            }
        )
    }

    val targetItem = editingItem
    if (targetItem != null) {
        AlertDialog(
            onDismissRequest = { editingItem = null },
            title = { Text("Catatan Keluhan Pasien", fontWeight = FontWeight.SemiBold) },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        text = "Catatan ini akan ikut digunakan Dokter Gigi Virtual saat konsultasi untuk ${targetItem.kelas.replace("_", " ")}.",
                        fontSize = 13.sp,
                        color = HistTextMuted
                    )
                    OutlinedTextField(
                        value = editedCatatan,
                        onValueChange = { editedCatatan = it.take(500) },
                        label = { Text("Keluhan / gejala tambahan") },
                        placeholder = { Text("Mis. Gusi terasa nyeri atau berdarah saat sikat gigi") },
                        minLines = 3,
                        maxLines = 5,
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        onUpdateCatatan(targetItem.id, editedCatatan)
                        editingItem = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = HistPrimaryBlue)
                ) {
                    Text("Simpan")
                }
            },
            dismissButton = {
                TextButton(onClick = { editingItem = null }) {
                    Text("Batal", color = HistTextMuted)
                }
            }
        )
    }
}

