@Composable
private fun HistoryReportCard(
    item: DetectionHistoryEntity,
    onEditClick: () -> Unit,
    onDeleteClick: () -> Unit,
    onConsultClick: () -> Unit
) {
    val formattedDate = remember(item.timestamp) {
        SimpleDateFormat("dd MMM yyyy, HH:mm", Locale.forLanguageTag("id-ID")).format(Date(item.timestamp))
    }
    val formattedConfidence = remember(item.confidence) {
        String.format(Locale.US, "%.1f%%", item.confidence * 100f)
    }

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(14.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.dp, HistBorderHairline)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = item.kelas.replace("_", " "),
                        color = HistTextPrimary,
                        fontSize = 17.sp,
                        fontWeight = FontWeight.SemiBold
                    )
                    Spacer(modifier = Modifier.height(2.dp))
                    Text(
                        text = "Keyakinan $formattedConfidence  •  $formattedDate",
                        color = HistTextMuted,
                        fontSize = 12.sp
                    )
                }
                Spacer(modifier = Modifier.width(8.dp))
                UrgensiPill(urgensi = item.urgensi)
            }

            Spacer(modifier = Modifier.height(10.dp))
            Text(
                text = item.deskripsi,
                color = HistTextMuted,
                fontSize = 13.sp,
                maxLines = 3,
                overflow = TextOverflow.Ellipsis
            )

            Spacer(modifier = Modifier.height(10.dp))
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(HistBackgroundLight, RoundedCornerShape(8.dp))
                    .padding(10.dp)
            ) {
                Text(
                    text = if (item.catatanKeluhan.isNotBlank()) {
                        "Catatan keluhan: ${item.catatanKeluhan}"
                    } else {
                        "Belum ada catatan keluhan tambahan."
                    },
                    color = if (item.catatanKeluhan.isNotBlank()) HistTextPrimary else HistTextMuted,
                    fontSize = 12.sp
                )
            }

            Spacer(modifier = Modifier.height(12.dp))
            HorizontalDivider(color = HistBorderHairline)
            Spacer(modifier = Modifier.height(10.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                OutlinedButton(
                    onClick = onEditClick,
                    border = BorderStroke(1.dp, HistBorderHairline),
                    shape = RoundedCornerShape(10.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                ) {
                    Icon(Icons.Filled.EditNote, contentDescription = null, tint = HistPrimaryBlue, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text("Catatan", color = HistTextPrimary, fontSize = 13.sp)
                }

                IconButton(onClick = onDeleteClick) {
                    Icon(Icons.Filled.Delete, contentDescription = "Hapus riwayat", tint = RedError)
                }

                Spacer(modifier = Modifier.weight(1f))

                Button(
                    onClick = onConsultClick,
                    colors = ButtonDefaults.buttonColors(containerColor = HistPrimaryBlue),
                    shape = RoundedCornerShape(10.dp),
                    contentPadding = PaddingValues(horizontal = 14.dp, vertical = 8.dp)
                ) {
                    Icon(Icons.AutoMirrored.Filled.Chat, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Tanya Chatbot", fontSize = 13.sp)
                }
            }
        }
    }
}

@Composable
private fun UrgensiPill(urgensi: String) {
    val (label, bg, fg) = when (urgensi.uppercase()) {
        "EDUKASI_MANDIRI" -> Triple("Edukasi Mandiri", GreenSoft, GreenSuccess)
        "KONTROL_RUTIN" -> Triple("Kontrol Rutin", AmberSoft, AmberText)
        "SEGERA_KE_DOKTER" -> Triple("Segera ke Dokter", RedSoft, RedError)
        else -> Triple(urgensi, SurfaceBlue, HistTextPrimary)
    }

    Box(
        modifier = Modifier
            .background(bg, RoundedCornerShape(8.dp))
            .padding(horizontal = 10.dp, vertical = 5.dp)
    ) {
        Text(
            text = label,
            color = fg,
            fontSize = 11.sp,
            fontWeight = FontWeight.SemiBold
        )
    }
}
